import java.util.Arrays;

public class FindFirstAndLastPosition {

    public int[] searchRange(int[] nums, int target) {
        return new int[]{lowerBound(nums, target), upperBound(nums, target)};
    }

    /** 找第一个等于 target 的位置，不存在返回 -1 */
    private int lowerBound(int[] nums, int target) {
        int left = 0, right = nums.length - 1, result = -1;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (nums[mid] == target) {
                result = mid;       // 命中，记录答案
                right = mid - 1;    // 继续向左找更早的
            } else if (nums[mid] < target) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        return result;
    }

    /** 找最后一个等于 target 的位置，不存在返回 -1 */
    private int upperBound(int[] nums, int target) {
        int left = 0, right = nums.length - 1, result = -1;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (nums[mid] == target) {
                result = mid;       // 命中，记录答案
                left = mid + 1;     // 继续向右找更晚的
            } else if (nums[mid] < target) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        return result;
    }

    public static void main(String[] args) {
        FindFirstAndLastPosition s = new FindFirstAndLastPosition();
        System.out.println(Arrays.toString(s.searchRange(new int[]{5,7,7,8,8,10}, 8))); // [3, 4]
        System.out.println(Arrays.toString(s.searchRange(new int[]{5,7,7,8,8,10}, 6))); // [-1, -1]
        System.out.println(Arrays.toString(s.searchRange(new int[]{}, 0)));              // [-1, -1]
        System.out.println(Arrays.toString(s.searchRange(new int[]{2,2}, 2)));           // [0, 1]
    }
}
